sys_ws_operation.operation_script:
(function process(request, response) {
    var requestBody = request.body.data;
    gs.info("🔵 Incoming API Request for update: " + JSON.stringify(requestBody));

    if (!requestBody || !requestBody.u_created_by || !requestBody.u_instance_url) {
        gs.error("❌ Missing required data: u_created_by or instance_url");
        response.setStatus(400);
        response.setBody({ error: "Missing required data: u_created_by or instance_url" });
        return;
    }

    // 🔹 Step 1: Find System Property to Update (procurement.form)
    var sysPropGr = new GlideRecord("sys_properties");
    sysPropGr.addQuery("name", "procurement.form"); // Target system property
    sysPropGr.query();

    if (sysPropGr.next()) {
        gs.info("✅ System Property Found: Updating procurement.form");

        var newValue = JSON.stringify(requestBody); // Storing the request body as the new value
        gs.info("📝 New Value for System Property: " + newValue);

        sysPropGr.value = newValue;
        var updateResult = sysPropGr.update();

        if (updateResult) {
            gs.info("✅ System Property Successfully Updated!");
            response.setStatus(200);
            response.setBody({ message: "✅ System Property updated successfully!", property_name: "procurement.form" });
        } else {
            gs.error("❌ Update Failed for System Property: procurement.form");
            response.setStatus(500);
            response.setBody({ error: "Update failed for system property: procurement.form" });
        }
    } else {
        gs.warn("❌ System Property 'procurement.form' not found");
        response.setStatus(404);
        response.setBody({ error: "System Property 'procurement.form' not found" });
    }
})(request, response);




